S = "Hakeem Force Academy"
QS = [
(S, "In which year did Dr Abdul Qadeer Khan, the father of Pakistan's nuclear programme, die?", ["2019", "2020", "2022", "2021"], 3, "Dr Abdul Qadeer Khan died in Islamabad on 10 October 2021 at the age of 85.", "He was buried with state honours in the H-8 graveyard, Islamabad.", [2258]),
(S, "In which year did Hazrat Khadija (RA), the first wife of the Holy Prophet (PBUH), die?", ["619 CE", "622 CE", "610 CE", "632 CE"], 0, "Hazrat Khadija (RA) died in 619 CE, in the 10th year of prophethood, a few days after the death of Abu Talib.", "That year is known as the Year of Sorrow (Aam ul Huzn).", [1408]),
(S, "On which date did Sir Syed Ahmad Khan die?", ["27 March 1898", "27 March 1897", "17 October 1898", "27 March 1908"], 0, "Sir Syed Ahmad Khan died on 27 March 1898 in Aligarh.", "He was born on 17 October 1817 in Delhi and founded the Aligarh Muslim University movement.", [116]),
(S, "How old was the Holy Prophet (PBUH) when his mother Bibi Amna died?", ["2 years", "4 years", "8 years", "6 years"], 3, "Bibi Amna died at a place called Abwa while returning from Madina, when the Prophet (PBUH) was about 6 years old.", "After her death his grandfather Abdul Muttalib took care of him.", [1912]),
(S, "Which word is a synonym of 'difference'?", ["Similarity", "Disparity", "Equality", "Agreement"], 1, "Disparity means a noticeable difference between things.", "The antonym of difference is similarity.", [2867]),
(S, "Which two numbers have a sum of 28 and a difference of 4?", ["18 and 10", "15 and 13", "16 and 12", "20 and 8"], 2, "16 + 12 = 28 and 16 - 12 = 4. Larger number = (28 + 4)/2 = 16.", "For sum S and difference D, the numbers are (S+D)/2 and (S-D)/2.", [4332]),
(S, "Which one is different: 7D, 9G, 4A, 6C?", ["7D", "9G", "4A", "6C"], 1, "Letter positions are D=4, G=7, A=1, C=3. Number minus letter position gives 3, 2, 3, 3, so 9G breaks the pattern.", "Position of a letter is its place in the alphabet (A=1, B=2 and so on).", [4201]),
(S, "Which digit is neither positive nor negative?", ["1", "0", "-1", "10"], 1, "Zero is neither positive nor negative.", "Zero is an even number and the additive identity.", [2439]),
(S, "What is the hundreds digit in the number 970?", ["7", "0", "9", "97"], 2, "In 970 the digits from left are hundreds (9), tens (7) and ones (0).", "The place values go ones, tens, hundreds, thousands.", [3142]),
(S, "In which province of Pakistan is Kot Diji located?", ["Punjab", "Balochistan", "Khyber Pakhtunkhwa", "Sindh"], 3, "Kot Diji is a town and fort in Khairpur district of Sindh.", "The Kot Diji site gave its name to the Kot Diji culture, an early Indus Valley civilisation phase.", [170, 2223, 131, 3739, 3726]),
(S, "What is the synonym of 'disastrous'?", ["Catastrophic", "Fortunate", "Helpful", "Pleasant"], 0, "Disastrous means causing great harm or damage, which is the same as catastrophic.", "The noun form is disaster.", [343]),
(S, "What is the antonym of 'disastrous'?", ["Ruinous", "Fatal", "Fortunate", "Harmful"], 2, "Disastrous means very harmful or unlucky, so its opposite is fortunate or successful.", "Catastrophic is a synonym of disastrous.", [2981]),
(S, "Syed Ahmad Shaheed (Barelvi) was a disciple of which scholar?", ["Shah Abdul Aziz", "Sir Syed Ahmad Khan", "Shah Ismail Shaheed", "Mujaddid Alf Thani"], 0, "Syed Ahmad Shaheed studied under and was a disciple of Shah Abdul Aziz Dehlvi, son of Shah Waliullah.", "He led the Jihad Movement and was martyred at Balakot in 1831.", [2596]),
(S, "In which year was Prime Minister Khawaja Nazimuddin dismissed?", ["1951", "1952", "1953", "1954"], 2, "Khawaja Nazimuddin was dismissed on 17 April 1953.", "He had become Prime Minister after the assassination of Liaquat Ali Khan in 1951.", [303, 3642]),
(S, "Who dismissed Prime Minister Khawaja Nazimuddin in 1953?", ["Iskander Mirza", "Ghulam Muhammad", "Ayub Khan", "Chaudhry Muhammad Ali"], 1, "Governor General Ghulam Muhammad dismissed Nazimuddin even though he still had the support of the Assembly.", "Mohammad Ali Bogra was then appointed Prime Minister.", [4406]),
(S, "The United Nations resolved the dispute between India and Pakistan over which territory?", ["Kashmir", "Siachen only", "Sir Creek", "Hyderabad"], 0, "The UN Security Council passed resolutions in 1948 and 1949 calling for a plebiscite in Jammu and Kashmir.", "The UN Military Observer Group (UNMOGIP) monitors the ceasefire line in Kashmir.", [1610]),
(S, "What is the antonym of 'distraction'?", ["Amusement", "Confusion", "Concentration", "Diversion"], 2, "Distraction means something that takes attention away, so its opposite is concentration or focus.", "Diversion is a synonym of distraction.", [2970]),
(S, "Which is the largest district of Balochistan by area?", ["Khuzdar", "Chagai", "Quetta", "Kech"], 1, "Chagai covers about 44,748 square km, the largest area of any district in Balochistan.", "Quetta is the largest Balochistan district by population.", [3014]),
(S, "After how many years of Pakistan's creation did East Pakistan separate to become Bangladesh?", ["20", "24", "30", "9"], 1, "Pakistan came into being in 1947 and East Pakistan separated in December 1971, which is 24 years later.", "Bangladesh became independent on 16 December 1971.", [809]),
(S, "Who wrote the first Diwan (poetry collection) of Urdu?", ["Mirza Ghalib", "Wali Deccani", "Mir Taqi Mir", "Muhammad Quli Qutb Shah"], 3, "Muhammad Quli Qutb Shah of Golconda is regarded as the first Urdu poet to compile a Diwan (Kulliyat).", "Some sources give the honour of the first Diwan to Wali Deccani, so sources differ.", [4702, 230]),
(S, "Change into indirect speech: He said, \"I was doing my work honestly.\"", ["He said that he was doing his work honestly.", "He said that he had been doing his work honestly.", "He said that I had been doing my work honestly.", "He said that he did his work honestly."], 1, "With a past reporting verb, the past continuous 'was doing' changes to past perfect continuous 'had been doing', and 'I' and 'my' change to 'he' and 'his'.", "Past simple and past continuous both shift one tense back in indirect speech.", [1648]),
(S, "What is the synonym of 'doomed'?", ["Fated", "Free", "Lucky", "Safe"], 0, "Doomed means destined to a bad outcome, which is the same as fated.", "The noun doom means a terrible fate.", [320]),
(S, "What is the meaning of 'doomed'?", ["Very happy", "Destined to fail or suffer", "Full of energy", "Extremely brave"], 1, "Doomed means certain to meet a bad end or failure.", "Doom also refers to death or destruction.", [207]),
(S, "What is the antonym (opposite) of 'doomed'?", ["Fated", "Condemned", "Blessed", "Ruined"], 2, "Doomed means destined for misfortune, so its opposite is blessed or fortunate.", "Fated and condemned are synonyms of doomed.", [2982, 339]),
(S, "A train covers double the distance of a car. If the car covers 60 km in one hour, how much does the train cover in the same time?", ["30 km", "90 km", "120 km", "180 km"], 2, "Train distance = 2 x 60 = 120 km in the same hour.", "Speed equals distance divided by time.", [1960]),
(S, "On which date did the USA drop the atomic bomb on Hiroshima, Japan?", ["9 August 1945", "6 August 1945", "15 August 1945", "2 September 1945"], 1, "The first atomic bomb was dropped on Hiroshima on 6 August 1945.", "A second bomb hit Nagasaki on 9 August 1945.", [2464, 2474]),
(S, "What was the code name of the atomic bomb dropped on Hiroshima?", ["Fat Man", "Trinity", "Little Boy", "Big Ivan"], 2, "The uranium bomb dropped on Hiroshima was called Little Boy.", "Fat Man was the plutonium bomb dropped on Nagasaki.", [3239]),
(S, "What was the name of the nuclear bomb dropped on Nagasaki?", ["Little Boy", "Fat Man", "Castle Bravo", "Tsar Bomba"], 1, "The plutonium bomb dropped on Nagasaki on 9 August 1945 was called Fat Man.", "The bomb dropped on Hiroshima was named Little Boy.", [3536]),
]
